void VerletIntegration(Particle3D& particle, float deltaTime){
  particle.position += particle.velocity * deltaTime
                     + 0.5f * particle.acceleration * deltaTime * deltaTime;
  glm::vec3 oldAcceleration = particle.acceleration;
  particle.acceleration = glm::vec3(0.0f);
  SetGravity(particle);
  particle.velocity += 0.5f * (oldAcceleration + particle.acceleration) * deltaTime;
}

const DEFAULT_RULES: Record<Scope, Decision> = {
  read: 'allow',
  local_write: 'allow',
  destructive: 'ask',
  external: 'ask',
  system: 'ask',
};

setRule(scope: Scope, decision: Decision): void {
  if (scope === 'external' && decision === 'allow') {
    throw new Error('External actions always require approval ...');
  }
  this.rules[scope] = decision;
}
